// Generate a random seed and obtain an initialized State by value
u64 seed = *FUZZ_PARAM(u64);
XorShift128PlusPlus::State s = XorShift128PlusPlus::GetInitialState(seed);

// Persist the returned state for the fuzzer object pool
XorShift128PlusPlus::State *state_out = new XorShift128PlusPlus::State{s};

// Validation: State is trivially copyable; no error paths to assert. The heap-allocated copy remains valid after return.

// Default-construct a generator; deterministic stream equivalent to seed 0
XorShift128PlusPlus *rng = new XorShift128PlusPlus();

// Validation: Construction has no failure mode; rng is live and returned to pool.

// Access the current internal state by const reference
const XorShift128PlusPlus::State &st = rng->GetState();

// Copy the state to a new heap object to keep it valid beyond this call
XorShift128PlusPlus::State *state_copy = new XorShift128PlusPlus::State{st};

// Validation: We do not expose the internal reference; instead, a deep copy is output alongside the still-alive rng.

// Obtain a mutable pointer to internal state; pointer is only valid while rng is alive
XorShift128PlusPlus::State *st = rng->GetMutableStatePtr();

// Mutate the state with fuzzed values to exercise write paths
st->s0 = *FUZZ_PARAM(u64);
st->s1 = *FUZZ_PARAM(u64);

// Do not return the internal pointer; only return rng which owns it
// Validation: Lifetime constraint is respected; internal pointer not leaked to pool.

// Prepare a caller-managed State and set it into the generator
XorShift128PlusPlus::State tmp;
tmp.s0 = *FUZZ_PARAM(u64);
tmp.s1 = *FUZZ_PARAM(u64);

// SetState copies contents; no thread-safety concerns in this single-threaded harness
rng->SetState(tmp);

// Validation: tmp is a local reference source; rng persists and is returned.

// Reseed with any 64-bit value (valid for all values)
u64 seed = *FUZZ_PARAM(u64);
rng->Reset(seed);

// Validation: Reset has no failure mode; rng remains valid and is returned.

// Generate a few values to exercise state transitions
(void)rng->Next();
(void)rng->Next();
(void)rng->Next();

// Validation: No parameters or error paths; rng remains valid and is returned.

// n must be > 0; enforce constraint to avoid division by zero during bound computation
u64 n = *FUZZ_PARAM(u64);
if (n == 0) { FUZZ_BAIL(); }

// Exercise rejection sampling path; call multiple times to increase coverage
(void)rng->NextRange(n);
(void)rng->NextRange(n);

// Validation: Input constraint enforced (n>0); rng remains valid and is returned.
